                                    {%- if rhino_card_media.width >= 720 -%}{{ rhino_card_media | image_url: width: 720 }} 720w,{%- endif -%}
                                    {%- if rhino_card_media.width >= 940 -%}{{ rhino_card_media | image_url: width: 940 }} 940w,{%- endif -%}
